param([string]$ProjectDirectory=(Split-Path $PSScriptRoot -Parent),[string]$EnvironmentFile="C:\PerformanceTracker\config\.env.production.local",[string]$BackupLog="C:\PerformanceTracker\backups\backup-operations.jsonl",[string]$AuditExportLog="C:\PerformanceTracker\audit-exports\audit-export-operations.jsonl",[string]$AlertDirectory="C:\PerformanceTracker\logs\alerts",[string]$ApplicationLogDirectory="C:\PerformanceTracker\logs\application")
$ErrorActionPreference="Stop";$project=[System.IO.Path]::GetFullPath($ProjectDirectory);$worker=Join-Path $project "scripts\monitor-production.ps1";if(-not(Test-Path -LiteralPath $worker)){throw "Monitor worker not found"};if(-not(Test-Path -LiteralPath $EnvironmentFile)){throw "Protected production environment file not found"}
foreach($value in @($EnvironmentFile,$worker,$BackupLog,$AuditExportLog,$AlertDirectory,$ApplicationLogDirectory)){if($value.Contains("'")){throw "Monitor paths may not contain apostrophes"}}
$command="`$lines=Get-Content -LiteralPath '$EnvironmentFile';foreach(`$line in `$lines){if(`$line -match '^([A-Z0-9_]+)=(.*)$'){[Environment]::SetEnvironmentVariable(`$matches[1],`$matches[2],'Process')}};& '$worker' -BackupLog '$BackupLog' -AuditExportLog '$AuditExportLog' -AlertDirectory '$AlertDirectory' -ApplicationLogDirectory '$ApplicationLogDirectory'"
$action=New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -NonInteractive -ExecutionPolicy AllSigned -Command `"$command`"";$trigger=New-ScheduledTaskTrigger -Once -At(Get-Date).AddMinutes(1)-RepetitionInterval(New-TimeSpan -Minutes 5);$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit(New-TimeSpan -Minutes 2)
Register-ScheduledTask -TaskName "Performance-Tracker-Operations-Monitor" -Action $action -Trigger $trigger -Settings $settings -Description "Detects Performance Tracker application, job, scanner, authentication, and backup failures" -Force
